false},{"key":"notice_id","official_label":"Notice ID (if listed on your notice)","help":null,"type":"notice_id","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false}],"benefit_tiers":[],"payout_options":[{"value":"check","official_label":"Check"},{"value":"other","official_label":"Other payment method listed on the official form"}],"form_field_order":["member.first_name","member.last_name","member.legal_name","member.email","member.phone","member.address.line1","member.address.line2","member.address.city","member.address.state","member.address.zip","answers.class_member","answers.subscription_email","answers.notice_id","payout_method"],"jev_rules":[],"desk_notes":"Official path is subscribe.rollingstone.com/krivin-rs. Fill name, address, email and the subscription email from the packet. Stop if a login, captcha or payment-account field appears. Never collect PayPal/Venmo account details. Never submit a test identity. Policy stays draft until a legal_reviewer approves after the dry-run."}'::jsonb);
    raise notice 'inserted spec draft rolling-stone-magazine-lifetime-subscription v%', v_spec_version;
  end if;
  if exists (
